public class CountdownTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("countdown(3)", "3 2 1 go", Countdown.countdown(3));
        check("countdown(0)", "go", Countdown.countdown(0));
        check("countdown(1)", "1 go", Countdown.countdown(1));
        check("countdown(5)", "5 4 3 2 1 go", Countdown.countdown(5));
        check("countdown(10) starts with 10", true, Countdown.countdown(10).startsWith("10 9 8"));
        check("countdown(10) ends with go", true, Countdown.countdown(10).endsWith("1 go"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

